class Solution {
    private int[] parent;
    private int[] rank;

    public int largestComponentSize(int[] nums) {
        int max = 0;
        for (int num : nums) {
            max = Math.max(max, num);
        }
        parent = new int[max + 1];
        rank = new int[max + 1];
        for (int i = 0; i <= max; i++) {
            parent[i] = i;
        }

        for (int num : nums) {
            int x = num;
            for (int p = 2; p * p <= x; p++) {
                if (x % p == 0) {
                    union(num, p);
                    while (x % p == 0) {
                        x /= p;
                    }
                }
            }
            if (x > 1) {
                union(num, x);
            }
        }

        java.util.Map<Integer, Integer> count = new java.util.HashMap<>();
        int answer = 0;
        for (int num : nums) {
            int root = find(num);
            count.put(root, count.getOrDefault(root, 0) + 1);
            answer = Math.max(answer, count.get(root));
        }
        return answer;
    }

    private int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    private void union(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) {
            return;
        }
        if (rank[ra] < rank[rb]) {
            int tmp = ra;
            ra = rb;
            rb = tmp;
        }
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) {
            rank[ra]++;
        }
    }
}

