    public int largestComponentSize(int[] nums) {
        int max = 0;
        for (int num : nums) {
            max = Math.max(max, num);
        }
        int[] indexByValue = new int[max + 1];
        java.util.Arrays.fill(indexByValue, -1);
        for (int i = 0; i < nums.length; i++) {
            indexByValue[nums[i]] = i;
        }

        parent = new int[nums.length];
        size = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        for (int factor = 2; factor <= max; factor++) {
            int firstIndex = -1;
            for (int multiple = factor; multiple <= max; multiple += factor) {
