class Solution {
    public int largestComponentSize(int[] nums) {
        java.util.List<java.util.List<Integer>> factorsByIndex = new java.util.ArrayList<>();
        java.util.Map<Integer, java.util.List<Integer>> factorToIndices = new java.util.HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            java.util.List<Integer> factors = primeFactors(nums[i]);
            factorsByIndex.add(factors);
            for (int factor : factors) {
                factorToIndices.computeIfAbsent(factor, key -> new java.util.ArrayList<>()).add(i);
            }
        }

        boolean[] visited = new boolean[nums.length];
        java.util.Set<Integer> usedFactors = new java.util.HashSet<>();
        int answer = 0;
        for (int i = 0; i < nums.length; i++) {
            if (visited[i]) {
                continue;
            }
            int count = 0;
            java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
            queue.addLast(i);
            visited[i] = true;
            while (!queue.isEmpty()) {
                int current = queue.removeFirst();
                count++;
                for (int factor : factorsByIndex.get(current)) {
                    if (!usedFactors.add(factor)) {
                        continue;
                    }
                    for (int next : factorToIndices.getOrDefault(factor, java.util.List.of())) {
                        if (!visited[next]) {
                            visited[next] = true;
                            queue.addLast(next);
                        }
                    }
                }
            }
            answer = Math.max(answer, count);
        }
        return answer;
    }

    private java.util.List<Integer> primeFactors(int value) {
        java.util.List<Integer> factors = new java.util.ArrayList<>();
        int x = value;
        for (int p = 2; p * p <= x; p++) {
            if (x % p == 0) {
                factors.add(p);
                while (x % p == 0) {
                    x /= p;
                }
            }
        }
        if (x > 1) {
            factors.add(x);
        }
        return factors;
    }
}
